-- 1. USERS
ON CONFLICT (id) DO UPDATE SET username = EXCLUDED.username, password_hash = EXCLUDED.password_hash, role = EXCLUDED.role, name = EXCLUDED.name, email = EXCLUDED.email, is_active = EXCLUDED.is_active;

-- 2. CLASSROOMS
