-- 3. TEACHERS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email, phone = EXCLUDED.phone, specialty = EXCLUDED.specialty, hourly_rate = EXCLUDED.hourly_rate, status = EXCLUDED.status, bio = EXCLUDED.bio;

-- 4. STUDENTS
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, email = EXCLUDED.email, phone = EXCLUDED.phone, date_of_birth = EXCLUDED.date_of_birth, gender = EXCLUDED.gender, address = EXCLUDED.address, status = EXCLUDED.status;

-- 5. CLASSES
ON CONFLICT (id) DO UPDATE SET code = EXCLUDED.code, name = EXCLUDED.name, subject = EXCLUDED.subject, teacher_id = EXCLUDED.teacher_id, room_id = EXCLUDED.room_id, tuition_fee = EXCLUDED.tuition_fee, schedule_days = EXCLUDED.schedule_days, shift_id = EXCLUDED.shift_id, meeting_link = EXCLUDED.meeting_link, status = EXCLUDED.status;

-- 6. CLASS_STUDENTS
ON CONFLICT (class_id, student_id) DO NOTHING;

-- 7. SCHEDULE_SLOTS
ON CONFLICT (id) DO UPDATE SET class_id = EXCLUDED.class_id, teacher_id = EXCLUDED.teacher_id, room_id = EXCLUDED.room_id, date = EXCLUDED.date, shift_id = EXCLUDED.shift_id, start_time = EXCLUDED.start_time, end_time = EXCLUDED.end_time, subject = EXCLUDED.subject, topic = EXCLUDED.topic, meeting_link = EXCLUDED.meeting_link, status = EXCLUDED.status;

-- 8. ATTENDANCE_RECORDS
ON CONFLICT (schedule_slot_id, student_id) DO UPDATE SET status = EXCLUDED.status, checkin_time = EXCLUDED.checkin_time, note = EXCLUDED.note, updated_by = EXCLUDED.updated_by, updated_at = EXCLUDED.updated_at;

-- 9. CLASS_REQUESTS
ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, reason = EXCLUDED.reason, target_schedule_slot_id = EXCLUDED.target_schedule_slot_id, status = EXCLUDED.status, reviewed_by = EXCLUDED.reviewed_by, review_note = EXCLUDED.review_note;

-- 10. TUITION_INVOICES
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, amount = EXCLUDED.amount, paid_amount = EXCLUDED.paid_amount, remaining_amount = EXCLUDED.remaining_amount, due_date = EXCLUDED.due_date, status = EXCLUDED.status, paid_date = EXCLUDED.paid_date, payment_method = EXCLUDED.payment_method, transaction_code = EXCLUDED.transaction_code;

-- 11. TEACHER_PAYROLL_PERIODS
ON CONFLICT (teacher_id, month) DO UPDATE SET total_slots = EXCLUDED.total_slots, total_hours = EXCLUDED.total_hours, hourly_rate = EXCLUDED.hourly_rate, gross_salary = EXCLUDED.gross_salary, bonus = EXCLUDED.bonus, deduction = EXCLUDED.deduction, net_salary = EXCLUDED.net_salary, status = EXCLUDED.status, paid_date = EXCLUDED.paid_date;

-- 12. AUDIT_LOGS
ON CONFLICT (id) DO NOTHING;

